CREATE TEMPORARY TABLE service_versions_expected_054 (
  service_no integer NOT NULL,
  version integer NOT NULL,
  schema_json jsonb NOT NULL,
  schema_hash text NOT NULL,
  PRIMARY KEY (service_no, version)
